func valueWorkerCredentialType(p unsafe.Pointer, c int32) any {
	r := (*workercredential.WorkerCredentialType)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return r.Code
	case 4:
		return r.Name
	case 5:
		if r.Description == "" {
			return nil
		}
		return r.Description
	case 6:
		return string(r.Category)
	case 7:
		return string(r.Status)
	case 8:
		return r.IsRequired
	case 9:
		if r.RequiredForDriverTypes == nil {
			return keel.EmptyJSONArray
		}
		return r.RequiredForDriverTypes
	case 10:
		return r.RenewalWindowDays
	case 11:
		if r.ValidityMonths == nil {
			return nil
		}
		return *r.ValidityMonths
	case 12:
		return r.RequiresNumber
	case 13:
		return r.RequiresDocument
	case 14:
		if r.ProfileField == "" {
			return nil
		}
		return string(r.ProfileField)
	case 15:
		return r.IsSystem
	case 16:
		return r.SortOrder
	case 17:
		return r.Version
	case 18:
		return r.CreatedAt
	case 19:
		return r.UpdatedAt
	case 20:
		return r.SearchVector
	}
	return nil
}

